CREATE TABLE IF NOT EXISTS capability_assignments(org_id TEXT NOT NULL REFERENCES organizations(id), capability TEXT NOT NULL CHECK(length(capability) BETWEEN 1 AND 128), connection_id TEXT NOT NULL REFERENCES connections(id) ON DELETE CASCADE, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0, 1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(org_id, capability));
CREATE INDEX IF NOT EXISTS capability_assignments_connection ON capability_assignments(connection_id);
CREATE TABLE IF NOT EXISTS external_entity_mappings(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), connection_id TEXT NOT NULL REFERENCES connections(id) ON DELETE CASCADE, entity_id TEXT NOT NULL CHECK(length(entity_id) BETWEEN 1 AND 256), display_name TEXT CHECK(display_name IS NULL OR length(display_name) BETWEEN 1 AND 256), is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN (0, 1)), source TEXT NOT NULL CHECK(source IN ('manual', 'sync')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS external_entity_mappings_lookup ON external_entity_mappings(org_id, connection_id);
CREATE TABLE IF NOT EXISTS capability_resolutions(execution_id TEXT NOT NULL REFERENCES executions(id), capability TEXT NOT NULL CHECK(length(capability) BETWEEN 1 AND 128), connection_id TEXT NOT NULL, integration_id TEXT NOT NULL, connection_updated_at TEXT, integration_revision TEXT NOT NULL, adapter_id TEXT NOT NULL, adapter_revision TEXT NOT NULL, transport TEXT NOT NULL, mapping_id TEXT, mapping_version TEXT, operation TEXT NOT NULL, resolved_at TEXT NOT NULL, PRIMARY KEY(execution_id, capability));
CREATE INDEX IF NOT EXISTS capability_resolutions_execution ON capability_resolutions(execution_id);
